import math

suspects = ["e10", "e27", "e13"] # ONLY recipients of c8 who also received d1-1 & d2-3!

logs_by_day = {
    1: [("e10", False), ("e10", False), ("e27", False), ("e27", False)],
    2: [("e10", True), ("e13", True)],
    3: [("e10", True), ("e13", False), ("e27", True)],
    4: [("e13", False)],
    5: [("e10", False), ("e13", False), ("e27", False)],
    6: [("e13", False)],
    7: [("e13", False), ("e13", False)],
    8: [("e27", False)],
    9: [], # NONE of e10, e27, e13 had ANY access on Day 9!
}

non_mole_decoy_holders = {1: 18, 2: 31, 3: 38, 4: 38, 5: 38, 6: 38, 7: 38, 8: 38, 9: 38}

interviews = {
    "e10": [
        True,  # D2 recent_documents
        False, # D3 contacts_outside
        False, # D4 workload
        False, # D5 access_needs
        False, # D6 contacts_outside
        False, # D6 recent_documents
        False, # D7 workload
        True,  # D8 recent_documents ("I'd have to check. I don't really keep track of what I open.")
        False, # D9 access_needs ("My access is a bit broad...")
    ],
    "e13": [
        True,  # D3 recent_documents
        False, # D5 access_needs
        False, # D6 contacts_outside
        False, # D7 workload
        False, # D8 recent_documents
        False, # D9 access_needs
    ],
    "e27": [
        False, # D4 recent_documents
        True,  # D5 access_needs
        True,  # D6 contacts_outside
        True,  # D7 workload
        False, # D8 recent_documents
        False, # D9 access_needs
    ],
}

canary_lr = {
    "e10": 0.95,
    "e27": 0.025,
    "e13": 0.025,
}

def pois_logpmf(k, lam):
    return k * math.log(lam) - lam - math.lgamma(k + 1)

for extra_random_frame in [0.0, 1.0]:
    print(f"=== Extra DSL random frame per day: {extra_random_frame} ===")
    log_post = {}
    for m in suspects:
        lp = math.log(canary_lr[m])
        for d in range(1, 10):
            day_logs = logs_by_day[d]
            for s in suspects:
                f_cnt = sum(1 for emp, ah in day_logs if emp == s and not ah)
                t_cnt = sum(1 for emp, ah in day_logs if emp == s and ah)
                if s == m:
                    lp += pois_logpmf(f_cnt, 0.7)
                    lp += pois_logpmf(t_cnt, 0.3)
                else:
                    frame_rate = 1.0 / non_mole_decoy_holders[d] + extra_random_frame / (non_mole_decoy_holders[d] + 1)
                    lp += pois_logpmf(f_cnt, 0.9)
                    lp += pois_logpmf(t_cnt, 0.1 + frame_rate)
        for s in suspects:
            for ev in interviews[s]:
                if s == m:
                    lp += math.log(0.24 if ev else 0.76)
                else:
                    lp += math.log(0.20 if ev else 0.80)
        log_post[m] = lp
    max_lp = max(log_post.values())
    probs = {s: math.exp(lp - max_lp) for s, lp in log_post.items()}
    tot = sum(probs.values())
    probs = {s: v / tot for s, v in probs.items()}
    for s in suspects:
        print(f"  {s}: P={probs[s]:.5f}")
    p10 = probs["e10"]
    for true_V in [0.70, 0.65]:
        ev_now = p10 * true_V + (1 - p10) * (-1.0)
        print(f"  EV(accuse e10 now | true_V={true_V:.2f}) = {ev_now:.5f}")
